package main

import (
	"bufio"
	"fmt"
	"os"
	"strings"

	"github.com/shopspring/decimal"
)

type LedgerRec struct { // 01 LEDGER-REC, 14 bytes
	BrBranch string // PIC X(2) @0 len=2
	BrAcct   string // PIC X(4) @2 len=4
	BrType   string // PIC X(1) @6 len=1
	BrAmt    decimal.Decimal // PIC 9(5)V99 @7 len=7
}

// Standalone working-storage items (VALUE shown after '=')
var WsEofFlag string = "N"         // PIC X len=1 = "N"
var WsFirstFlag string = "Y"       // PIC X len=1 = "Y"
var WsPrevBranch string = "  "     // PIC X(2) len=2 = SPACES
var WsPrevAcct string = "    "     // PIC X(4) len=4 = SPACES
var WsBal decimal.Decimal = decimal.New(0, 0)       // PIC S9(7)V99 len=9 = 0
var WsBranchTot decimal.Decimal = decimal.New(0, 0) // PIC S9(9)V99 len=11 = 0
var WsGrandTot decimal.Decimal = decimal.New(0, 0)  // PIC S9(9)V99 len=11 = 0
var WsSkipped int64 = 0            // PIC 99 len=2 = 0
var WsAmtEd string                 // PIC ZZ,ZZ9.99 len=9
var WsBalEd string                 // PIC -Z,ZZZ,ZZ9.99 len=13
var WsTotEd string                 // PIC -ZZZ,ZZZ,ZZ9.99 len=15

var ledgerLines []string
var ledgerIdx int
var CurRec LedgerRec

func pow10Int64(n int) int64 {
	var r int64 = 1
	for i := 0; i < n; i++ {
		r *= 10
	}
	return r
}

func storeSigned(v decimal.Decimal, intDigits int, scale int32) decimal.Decimal {
	t := v.Truncate(scale)
	scaled := t.Shift(scale).IntPart()
	exp := intDigits + int(scale)
	var mod int64 = 1
	for i := 0; i < exp; i++ {
		mod *= 10
	}
	var wrapped int64
	if scaled >= 0 {
		wrapped = scaled % mod
	} else {
		wrapped = -((-scaled) % mod)
	}
	return decimal.New(wrapped, -scale)
}

func storeBal(v decimal.Decimal) decimal.Decimal {
	return storeSigned(v, 7, 2)
}
func storeBranchTot(v decimal.Decimal) decimal.Decimal {
	return storeSigned(v, 9, 2)
}
func storeGrandTot(v decimal.Decimal) decimal.Decimal {
	return storeSigned(v, 9, 2)
}

func formatAmt(v decimal.Decimal) string {
	t := v.Truncate(2)
	if t.Sign() < 0 {
		t = t.Neg()
	}
	scaled := t.Shift(2).IntPart()
	if scaled < 0 {
		scaled = -scaled
	}
	intPart := scaled / 100
	frac := scaled % 100
	capN := 5
	mod := pow10Int64(capN)
	intMod := intPart % mod
	intStr := fmt.Sprintf("%05d", intMod)
	first := capN - 1
	for i := 0; i < capN; i++ {
		if intStr[i] != '0' {
			first = i
			break
		}
	}
	pat := "ZZ,ZZ9"
	var b strings.Builder
	di := 0
	for _, ch := range pat {
		if ch == ',' {
			if first < di {
				b.WriteByte(',')
			} else {
				b.WriteByte(' ')
			}
		} else {
			if di < first {
				b.WriteByte(' ')
			} else {
				b.WriteByte(intStr[di])
			}
			di++
		}
	}
	b.WriteByte('.')
	b.WriteString(fmt.Sprintf("%02d", frac))
	return b.String()
}

func formatBal(v decimal.Decimal) string {
	sign := " "
	if v.Sign() < 0 {
		sign = "-"
	}
	abs := v.Abs().Truncate(2)
	scaled := abs.Shift(2).IntPart()
	intPart := scaled / 100
	frac := scaled % 100
	capN := 7
	mod := pow10Int64(capN)
	intMod := intPart % mod
	intStr := fmt.Sprintf("%07d", intMod)
	first := capN - 1
	for i := 0; i < capN; i++ {
		if intStr[i] != '0' {
			first = i
			break
		}
	}
	pat := "Z,ZZZ,ZZ9"
	var b strings.Builder
	b.WriteString(sign)
	di := 0
	for _, ch := range pat {
		if ch == ',' {
			if first < di {
				b.WriteByte(',')
			} else {
				b.WriteByte(' ')
			}
		} else {
			if di < first {
				b.WriteByte(' ')
			} else {
				b.WriteByte(intStr[di])
			}
			di++
		}
	}
	b.WriteByte('.')
	b.WriteString(fmt.Sprintf("%02d", frac))
	return b.String()
}

func formatTot(v decimal.Decimal) string {
	sign := " "
	if v.Sign() < 0 {
		sign = "-"
	}
	abs := v.Abs().Truncate(2)
	scaled := abs.Shift(2).IntPart()
	intPart := scaled / 100
	frac := scaled % 100
	capN := 9
	mod := pow10Int64(capN)
	intMod := intPart % mod
	intStr := fmt.Sprintf("%09d", intMod)
	first := capN - 1
	for i := 0; i < capN; i++ {
		if intStr[i] != '0' {
			first = i
			break
		}
	}
	pat := "ZZZ,ZZZ,ZZ9"
	var b strings.Builder
	b.WriteString(sign)
	di := 0
	for _, ch := range pat {
		if ch == ',' {
			if first < di {
				b.WriteByte(',')
			} else {
				b.WriteByte(' ')
			}
		} else {
			if di < first {
				b.WriteByte(' ')
			} else {
				b.WriteByte(intStr[di])
			}
			di++
		}
	}
	b.WriteByte('.')
	b.WriteString(fmt.Sprintf("%02d", frac))
	return b.String()
}

func MainPara() {
	f, err := os.Open("input.dat")
	if err != nil {
		fmt.Fprintln(os.Stderr, err.Error())
		os.Exit(1)
	}
	var lines []string
	scanner := bufio.NewScanner(f)
	for scanner.Scan() {
		lines = append(lines, scanner.Text())
	}
	if err := scanner.Err(); err != nil {
		fmt.Fprintln(os.Stderr, err.Error())
		os.Exit(1)
	}
	ledgerLines = lines
	ledgerIdx = 0
	ReadPara()
	for WsEofFlag != "Y" {
		ProcessPara()
	}
	if WsFirstFlag != "Y" {
		AcctBreakPara()
		BranchBreakPara()
	}
	f.Close()
	GrandPara()
}

func ReadPara() {
	if ledgerIdx >= len(ledgerLines) {
		WsEofFlag = "Y"
		return
	}
	line := ledgerLines[ledgerIdx]
	ledgerIdx++
	if len(line) < 14 {
		line = line + strings.Repeat(" ", 14-len(line))
	} else if len(line) > 14 {
		line = line[:14]
	}
	CurRec.BrBranch = line[0:2]
	CurRec.BrAcct = line[2:6]
	CurRec.BrType = line[6:7]
	amtStr := line[7:14]
	var n int64 = 0
	for i := 0; i < len(amtStr); i++ {
		c := amtStr[i]
		if c >= '0' && c <= '9' {
			n = n*10 + int64(c-'0')
		} else {
			n = n * 10
		}
	}
	CurRec.BrAmt = decimal.New(n, -2)
}

func ProcessPara() {
	if WsFirstFlag == "Y" {
		WsPrevBranch = CurRec.BrBranch
		WsPrevAcct = CurRec.BrAcct
		WsFirstFlag = "N"
	} else {
		if CurRec.BrBranch != WsPrevBranch {
			AcctBreakPara()
			BranchBreakPara()
			WsPrevBranch = CurRec.BrBranch
			WsPrevAcct = CurRec.BrAcct
		} else {
			if CurRec.BrAcct != WsPrevAcct {
				AcctBreakPara()
				WsPrevAcct = CurRec.BrAcct
			}
		}
	}
	PostPara()
	ReadPara()
}

func PostPara() {
	WsAmtEd = formatAmt(CurRec.BrAmt)
	if CurRec.BrType == "D" {
		WsBal = storeBal(WsBal.Add(CurRec.BrAmt))
		fmt.Printf("%s%s%s\n", CurRec.BrAcct, " D ", WsAmtEd)
	} else if CurRec.BrType == "C" {
		WsBal = storeBal(WsBal.Sub(CurRec.BrAmt))
		fmt.Printf("%s%s%s\n", CurRec.BrAcct, " C ", WsAmtEd)
	} else {
		WsSkipped = (WsSkipped + 1) % 100
		fmt.Printf("%s%s\n", CurRec.BrAcct, " ? SKIPPED")
	}
}

func AcctBreakPara() {
	WsBalEd = formatBal(WsBal)
	fmt.Printf("%s%s%s%s\n", "  ACCOUNT ", WsPrevAcct, " BALANCE:", WsBalEd)
	WsBranchTot = storeBranchTot(WsBranchTot.Add(WsBal))
	WsBal = decimal.New(0, -2)
}

func BranchBreakPara() {
	WsTotEd = formatTot(WsBranchTot)
	fmt.Printf("%s%s%s%s\n", " BRANCH ", WsPrevBranch, " TOTAL:", WsTotEd)
	WsGrandTot = storeGrandTot(WsGrandTot.Add(WsBranchTot))
	WsBranchTot = decimal.New(0, -2)
}

func GrandPara() {
	WsTotEd = formatTot(WsGrandTot)
	fmt.Printf("%s%s\n", "GRAND TOTAL:", WsTotEd)
	skippedStr := fmt.Sprintf("%02d", WsSkipped%100)
	fmt.Printf("%s%s\n", "SKIPPED: ", skippedStr)
}

func main() {
	MainPara()
}

