package main

import (
	"fmt"
	"os"
	"strings"

	"github.com/shopspring/decimal"
)

type LedgerRec struct {
	BrBranch string
	BrAcct   string
	BrType   string
	BrAmt    decimal.Decimal
}

var WsEofFlag string = "N"
var WsFirstFlag string = "Y"
var WsPrevBranch string = "  "
var WsPrevAcct string = "    "
var WsBal decimal.Decimal = decimal.NewFromInt(0)
var WsBranchTot decimal.Decimal = decimal.NewFromInt(0)
var WsGrandTot decimal.Decimal = decimal.NewFromInt(0)
var WsSkipped int64 = 0
var WsAmtEd string = ""
var WsBalEd string = ""
var WsTotEd string = ""

var curRec LedgerRec
var records []string
var recIdx int

func InputDone() bool {
	return WsEofFlag == "Y"
}
func FirstRecord() bool {
	return WsFirstFlag == "Y"
}

func cobDisplay(parts ...string) {
	s := strings.Join(parts, "")
	os.Stdout.WriteString(s + "\n")
}

func applySuppression(digits string, pattern string) string {
	out := make([]byte, len(pattern))
	di := 0
	significant := false
	for i := 0; i < len(pattern); i++ {
		c := pattern[i]
		if c == 'Z' || c == '9' {
			d := digits[di]
			di++
			if c == '9' {
				out[i] = d
				significant = true
			} else {
				if significant || d != '0' {
					out[i] = d
					significant = true
				} else {
					out[i] = ' '
				}
			}
		} else if c == ',' {
			if significant {
				out[i] = ','
			} else {
				out[i] = ' '
			}
		} else {
			out[i] = c
		}
	}
	return string(out)
}

func splitCents(v decimal.Decimal, intDigits int) (bool, int64, int64) {
	t := v.Truncate(2)
	powCents := decimal.New(1, int32(intDigits+2))
	cents := t.Shift(2).Truncate(0)
	rem := cents.Mod(powCents)
	if rem.IsZero() {
		return false, 0, 0
	}
	neg := cents.IsNegative()
	absRem := rem.Abs()
	c := absRem.IntPart()
	intMod := c / 100
	frac := c % 100
	return neg, intMod, frac
}

func formatAmtEd(v decimal.Decimal) string {
	_, intMod, frac := splitCents(v, 5)
	digits := fmt.Sprintf("%05d", intMod)
	intStr := applySuppression(digits, "ZZ,ZZ9")
	return intStr + "." + fmt.Sprintf("%02d", frac)
}

func formatBalEd(v decimal.Decimal) string {
	neg, intMod, frac := splitCents(v, 7)
	digits := fmt.Sprintf("%07d", intMod)
	intStr := applySuppression(digits, "Z,ZZZ,ZZ9")
	sign := " "
	if neg {
		sign = "-"
	}
	return sign + intStr + "." + fmt.Sprintf("%02d", frac)
}

func formatTotEd(v decimal.Decimal) string {
	neg, intMod, frac := splitCents(v, 9)
	digits := fmt.Sprintf("%09d", intMod)
	intStr := applySuppression(digits, "ZZZ,ZZZ,ZZ9")
	sign := " "
	if neg {
		sign = "-"
	}
	return sign + intStr + "." + fmt.Sprintf("%02d", frac)
}

func storeBal(d decimal.Decimal) decimal.Decimal {
	t := d.Truncate(2)
	powCents := decimal.New(1, 9)
	cents := t.Shift(2).Truncate(0)
	rem := cents.Mod(powCents)
	return rem.Shift(-2)
}

func storeBranchTot(d decimal.Decimal) decimal.Decimal {
	t := d.Truncate(2)
	powCents := decimal.New(1, 11)
	cents := t.Shift(2).Truncate(0)
	rem := cents.Mod(powCents)
	return rem.Shift(-2)
}

func storeGrandTot(d decimal.Decimal) decimal.Decimal {
	t := d.Truncate(2)
	powCents := decimal.New(1, 11)
	cents := t.Shift(2).Truncate(0)
	rem := cents.Mod(powCents)
	return rem.Shift(-2)
}

func loadRecords() {
	data, err := os.ReadFile("input.dat")
	if err != nil {
		fmt.Fprintln(os.Stderr, err)
		os.Exit(1)
	}
	if len(data) == 0 {
		records = nil
		recIdx = 0
		return
	}
	s := string(data)
	parts := strings.Split(s, "\n")
	if len(parts) > 0 && parts[len(parts)-1] == "" {
		if strings.HasSuffix(s, "\n") {
			parts = parts[:len(parts)-1]
		}
	}
	for i, p := range parts {
		if strings.HasSuffix(p, "\r") {
			parts[i] = p[:len(p)-1]
		}
	}
	records = parts
	recIdx = 0
}

func parseRecord(line string) LedgerRec {
	var r LedgerRec
	s := line
	if len(s) < 14 {
		s = s + strings.Repeat(" ", 14-len(s))
	} else if len(s) > 14 {
		s = s[:14]
	}
	r.BrBranch = s[0:2]
	r.BrAcct = s[2:6]
	r.BrType = s[6:7]
	amtStr := s[7:14]
	var n int64 = 0
	for i := 0; i < len(amtStr); i++ {
		c := amtStr[i]
		if c >= '0' && c <= '9' {
			n = n*10 + int64(c-'0')
		} else {
			n = n * 10
		}
	}
	r.BrAmt = decimal.New(n, -2)
	return r
}

func ReadPara() {
	if recIdx >= len(records) {
		WsEofFlag = "Y"
		return
	}
	curRec = parseRecord(records[recIdx])
	recIdx++
}

func ProcessPara() {
	if FirstRecord() {
		WsPrevBranch = curRec.BrBranch
		WsPrevAcct = curRec.BrAcct
		WsFirstFlag = "N"
	} else {
		if curRec.BrBranch != WsPrevBranch {
			AcctBreakPara()
			BranchBreakPara()
			WsPrevBranch = curRec.BrBranch
			WsPrevAcct = curRec.BrAcct
		} else {
			if curRec.BrAcct != WsPrevAcct {
				AcctBreakPara()
				WsPrevAcct = curRec.BrAcct
			}
		}
	}
	PostPara()
	ReadPara()
}

func PostPara() {
	WsAmtEd = formatAmtEd(curRec.BrAmt)
	switch curRec.BrType {
	case "D":
		WsBal = storeBal(WsBal.Add(curRec.BrAmt))
		cobDisplay(curRec.BrAcct, " D ", WsAmtEd)
	case "C":
		WsBal = storeBal(WsBal.Sub(curRec.BrAmt))
		cobDisplay(curRec.BrAcct, " C ", WsAmtEd)
	default:
		WsSkipped = (WsSkipped + 1) % 100
		cobDisplay(curRec.BrAcct, " ? SKIPPED")
	}
}

func AcctBreakPara() {
	WsBalEd = formatBalEd(WsBal)
	cobDisplay("  ACCOUNT ", WsPrevAcct, " BALANCE:", WsBalEd)
	WsBranchTot = storeBranchTot(WsBranchTot.Add(WsBal))
	WsBal = decimal.NewFromInt(0)
}

func BranchBreakPara() {
	WsTotEd = formatTotEd(WsBranchTot)
	cobDisplay(" BRANCH ", WsPrevBranch, " TOTAL:", WsTotEd)
	WsGrandTot = storeGrandTot(WsGrandTot.Add(WsBranchTot))
	WsBranchTot = decimal.NewFromInt(0)
}

func GrandPara() {
	WsTotEd = formatTotEd(WsGrandTot)
	cobDisplay("GRAND TOTAL:", WsTotEd)
	cobDisplay("SKIPPED: ", fmt.Sprintf("%02d", WsSkipped))
}

func MainPara() {
	loadRecords()
	ReadPara()
	for !InputDone() {
		ProcessPara()
	}
	if !FirstRecord() {
		AcctBreakPara()
		BranchBreakPara()
	}
	GrandPara()
}

func main() {
	MainPara()
}
